test('metadata completion is explicit, includes saved imported records, sends only identity and version, and reports unavailable entries',async()=>{
 const items:Array<Record<string,unknown>>=[{...record,kind:'screen'},{...record,domain:'book',subjectId:'23456',kind:'book',source:'import',profileId:'private_owner'},{...record,domain:'music',subjectId:'34567',kind:'music'}];const f=fixture({items});await settle(()=>!f.el('metadata').disabled);assert.ok(f.requests.every(request=>request.method==='GET'));
 f.setMetadataHandler(async body=>{const index=items.findIndex(item=>item.subjectId===body.subjectId),original=items[index],changed=index<2,item=changed?{...original,kind:index===0?'series':original.kind,coverUrl:'https://img1.doubanio.com/view/photo/public/p123.jpg',updatedAt:'2026-11-14T08:00:01Z'}:original;items[index]=item;f.setItems(items);return Response.json({item,changed,metadata:{status:changed?'complete':'unavailable'}});});
 f.click('metadata');await settle(()=>f.el('metadata-status').textContent?.startsWith('本页补全完成')===true);const requests=f.requests.filter(request=>request.path==='/api/life/douban/metadata');assert.equal(requests.length,3);assert.deepEqual(requests[1].body,{profileId:'private_owner',domain:'book',subjectId:'23456',expectedUpdatedAt:STAMP,confirmed:true});assert.ok(requests.every(request=>Object.keys(request.body!).sort().join(',')==='confirmed,domain,expectedUpdatedAt,profileId,subjectId'));assert.equal(f.el('metadata-status').textContent,'本页补全完成：已处理 3 / 3 条，更新 2 条，暂无法获取 1 条。');assert.match(f.el('list').textContent??'',/电视剧/);assert.equal(f.requests.some(request=>request.path==='/api/life/douban/sync'||request.path==='/api/life/douban/classification'),false);
});

