test('invalid UTF-8 files are rejected locally before parsing or sending a private preview',async()=>{
 const f=fixture({connected:false,items:[]});await settle(()=>f.el('page').getAttribute('aria-busy')==='false');f.completeImport();f.setInvalidFiles();f.submit('import-form');await settle(()=>f.el('import-status').textContent?.includes('另存为 UTF-8')===true);assert.equal(f.localParserCalls.length,0);assert.equal(f.requests.some(request=>request.path==='/api/life/douban/import'),false);assert.equal(f.el('import-confirm').disabled,true);assert.equal(f.el('import-profile').value,'private_owner');assert.equal((f.registrations[1].isDirty as ()=>boolean)(),true);
});

function restrictedRun(){return{...run('partial',4),sources:{screen:{status:'failed',pages:0,received:0,total:null,errorCode:'DOUBAN_SOURCE_TIMEOUT'},book:{status:'blocked',pages:0,received:0,total:null,errorCode:'DOUBAN_SOURCE_BLOCKED'},music:{status:'complete',pages:1,received:2,total:2,errorCode:null}},rss:{status:'failed',received:0,errorCode:'DOUBAN_SOURCE_BLOCKED'}};}

function extensionProgress(status='running',pages=0,received=0){return{status,sources:{screen:{status:status==='running'?'pending':'complete',pages,received,total:received},book:{status:status==='running'?'pending':'complete',pages:0,received:0,total:0},music:{status:status==='running'?'pending':'complete',pages:0,received:0,total:0}},pages,received,accountProfileId:'mine'};}
function replyExtension(message:Record<string,unknown>,reply:(value:unknown)=>void,items:Array<Record<string,unknown>>=[],done=true){if(message.action==='CONNECT')reply({ok:true,data:{extensionVersion:'1.0.1',protocolVersion:1}});else if(message.action==='START')reply({ok:true,data:{runId:RUN_ID,step:0,progress:extensionProgress(),done:false}});else if(message.action==='STEP')reply({ok:true,data:{runId:RUN_ID,step:Number(message.step)+1,items,progress:extensionProgress(done?'completed':'running',Number(message.step)+1,items.length),done}});else if(message.action==='LOGIN')reply({ok:true,data:{opened:true}});else if(message.action==='CANCEL')reply({ok:true,data:{cancelled:true}});else assert.fail('Unexpected extension action '+message.action);}

test('browser extension connection and normal login only happen on explicit clicks and never claim a login from installation',async()=>{
 const f=fixture({extension:true});await settle(()=>!f.el('browser-sync').disabled);assert.equal(f.extensionCalls.length,0);assert.equal(f.el('browser-install').querySelector('a[download]')?.getAttribute('href'),'/downloads/jiashu-douban-extension.zip');assert.match(f.el('browser-install').textContent??'',/同一个 Chrome 或 Edge/);f.setExtensionHandler(replyExtension);f.click('browser-connect');await settle(()=>f.el('browser-status').textContent?.includes('可连接')===true);assert.deepEqual(f.extensionCalls.map(call=>call.message.action),['CONNECT']);assert.equal(f.requests.filter(request=>request.method!=='GET').length,0);f.click('browser-login');await settle(()=>f.el('browser-status').textContent?.startsWith('已打开豆瓣登录页')===true);assert.deepEqual(f.extensionCalls.map(call=>call.message.action),['CONNECT','LOGIN']);assert.ok(f.extensionCalls.every(call=>call.id==='gbcgjkicjfbaakippafhhpadfkfifaeb'&&call.message.type==='JIASHU_DOUBAN'&&call.message.version===1&&call.message.profileId==='mine'));assert.match(String(f.extensionCalls[0].message.ownerKey),/^[a-f0-9-]{36}$/);assert.equal(f.extensionCalls[0].message.ownerKey,f.extensionCalls[1].message.ownerKey);
});

